import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(\d+(?:\.\d+)?|\.\d+)"
_COMPONENT = re.compile(r"\s*" + _NUM + r"\s*([A-Za-z]+)")
_ISO = re.compile(
    r"P(?:" + _NUM + r"W)?(?:" + _NUM + r"D)?"
    r"(?:T(?:" + _NUM + r"H)?(?:" + _NUM + r"M)?(?:" + _NUM + r"S)?)?"
)
_CLOCK = re.compile(r"\d+(?::\d+){1,2}")


def _to_seconds(value: str, factor: int) -> Decimal:
    return Decimal(value) * factor


def _finish(total: Decimal) -> int:
    return int(total.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare non-negative integer: seconds.
    if s.isdigit() and s.isascii():
        return int(s)

    # Clock notation: hh:mm:ss or mm:ss.
    if ":" in s:
        if not _CLOCK.fullmatch(s):
            raise ValueError(f"invalid clock duration: {text!r}")
        fields = [int(f) for f in s.split(":")]
        for f in fields[1:]:
            if f >= 60:
                raise ValueError(f"clock field out of range: {text!r}")
        total = 0
        for f in fields:
            total = total * 60 + f
        return total

    # ISO 8601 duration.
    if s[0] in "Pp":
        upper = s.upper()
        m = _ISO.fullmatch(upper)
        if not m or upper == "P" or upper.endswith("T"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        factors = [604800, 86400, 3600, 60, 1]
        total = Decimal(0)
        for value, factor in zip(m.groups(), factors):
            if value is not None:
                total += _to_seconds(value, factor)
        return _finish(total)

    # Number+unit components, optionally separated by spaces.
    total = Decimal(0)
    pos = 0
    n = len(s)
    while pos < n:
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += _to_seconds(m.group(1), _UNITS[unit])
        pos = m.end()
        while pos < n and s[pos].isspace():
            pos += 1
    if total < 0:
        raise ValueError("negative duration")
    return _finish(total)

